import java.util.concurrent.RecursiveTask;
import java.util.concurrent.ForkJoinPool;

public class SumTask extends RecursiveTask<Long> {
    private final long[] numbers;
    private final int start, end;
    private static final int THRESHOLD = 10_000;

    public SumTask(long[] numbers, int start, int end) {
        this.numbers = numbers;
        this.start = start;
        this.end = end;
    }

    @Override
    protected Long compute() {
        if (end - start <= THRESHOLD) {
            long sum = 0;
            for (int i = start; i < end; i++) {
                if (numbers[i] < 0) {
                    throw new IllegalArgumentException("Negative values not allowed: " + numbers[i]);
                }
                sum += numbers[i];
            }
            return sum;
        } else {
            int mid = start + (end - start) / 2;
            SumTask leftTask = new SumTask(numbers, start, mid);
            SumTask rightTask = new SumTask(numbers, mid, end);

            leftTask.fork(); // Asynchronous push to work queue
            long rightResult = rightTask.compute(); // Directly compute right
            long leftResult = leftTask.join(); // Joins and triggers throwIfFailed internally if leftTask threw

            return leftResult + rightResult;
        }
    }

    public static void main(String[] args) {
        long[] data = new long[50_000];
        ForkJoinPool pool = ForkJoinPool.commonPool();
        SumTask task = new SumTask(data, 0, data.length);
        try {
            Long total = pool.invoke(task); // Safely handles fork, join, and exception propagation
            System.out.println("Sum: " + total);
        } catch (RuntimeException e) {
            System.err.println("Computation failed: " + e.getMessage());
        }
    }
}
